# ------------- new kinds -------------
def NK(n,a,d,s,tt,x=None,see=None,tg=None,m=None,r=None):
    k={"n":n,"a":a,"d":d,"s":s,"tt":tt}
    if x: k["x"]=x
    if see: k["see"]=see
    if tg: k["tg"]=tg
    if m: k["m"]=m
    if r: k["r"]=r
    return k
